/**
 * Embedded Base64 Default Assets
 * Ensures 100% offline and file:/// scheme export compatibility without CORS or Canvas tainting.
 * All card photos use pure PNG Data URIs for complete SVG foreignObject rasterization compatibility.
 */
const DEFAULT_ASSETS = {
  "assets/IMG_20261031_200600_743.jpg": "data:image/jpeg;base64,",
  "assets/tpl1/avatar_default.png": "data:image/png;base64,",
  "assets/tpl2/barcode.png": "data:image/png;base64,",
  "assets/tpl2/crest.png": "data:image/png;base64,",
  "assets/tpl2/photo_default.png": "data:image/png;base64,",
  "assets/tpl2/stamp.png": "data:image/png;base64,",
  "assets/tpl2/stars.svg": "data:image/svg+xml;base64,",
  "assets/tpl3/photo_default.png": "data:image/png;base64,",
  "assets/tpl4/barcode.svg": "data:image/svg+xml;base64,",
  "assets/tpl4/exh_a.png": "data:image/png;base64,",
  "assets/tpl4/exh_a.webp": "data:image/png;base64,",
  "assets/tpl4/exh_b.png": "data:image/png;base64,",
  "assets/tpl4/exh_b.webp": "data:image/png;base64,",
  "assets/tpl4/photo_default.png": "data:image/png;base64,",
  "assets/tpl4/photo_default.webp": "data:image/png;base64,",
  "assets/tpl4/stamp.png": "data:image/png;base64,",
  "assets/tpl4/stamp.webp": "data:image/png;base64,"
};

function getAssetDataUri(relPath) {
    if (typeof DEFAULT_ASSETS !== 'undefined' && DEFAULT_ASSETS[relPath]) {
        return DEFAULT_ASSETS[relPath];
    }
    return relPath;
}

function ensureImagesAreDataUrls(rootNode = document) {
    if (typeof DEFAULT_ASSETS === 'undefined') return;
    const imgs = rootNode.querySelectorAll('img');
    imgs.forEach(img => {
        const curSrc = img.src || '';
        if (curSrc.startsWith('data:image/')) return;
        for (const [relPath, dataUri] of Object.entries(DEFAULT_ASSETS)) {
            if (curSrc.endsWith(relPath) || img.getAttribute('src') === relPath) {
                img.src = dataUri;
                break;
            }
        }
    });
}

// Auto-run when DOM is ready or if file protocol is detected
if (typeof document !== 'undefined') {
    if (document.readyState === 'loading') {
        document.addEventListener('DOMContentLoaded', () => ensureImagesAreDataUrls(document));
    } else {
        ensureImagesAreDataUrls(document);
    }
}
